function sha256(msg) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = msg.length;
  const bytes = [];
  for (let i = 0; i < l; i++) bytes.push(msg.charCodeAt(i) & 0xff);
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const bitLen = l * 8;
  const hi = Math.floor(bitLen / 0x100000000) >>> 0, lo = bitLen >>> 0;
  bytes.push((hi>>>24)&0xff,(hi>>>16)&0xff,(hi>>>8)&0xff,hi&0xff,(lo>>>24)&0xff,(lo>>>16)&0xff,(lo>>>8)&0xff,lo&0xff);
  let h0=H[0],h1=H[1],h2=H[2],h3=H[3],h4=H[4],h5=H[5],h6=H[6],h7=H[7];
  const w = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < bytes.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = (((bytes[i+4*t]<<24) | (bytes[i+4*t+1]<<16) | (bytes[i+4*t+2]<<8) | bytes[i+4*t+3])) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t-15],7) ^ rotr(w[t-15],18) ^ (w[t-15]>>>3);
      const s1 = rotr(w[t-2],17) ^ rotr(w[t-2],19) ^ (w[t-2]>>>10);
      w[t] = (w[t-16] + s0 + w[t-7] + s1) >>> 0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,hh=h7;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      hh=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    h0=(h0+a)>>>0; h1=(h1+b)>>>0; h2=(h2+c)>>>0; h3=(h3+d)>>>0; h4=(h4+e)>>>0; h5=(h5+f)>>>0; h6=(h6+g)>>>0; h7=(h7+hh)>>>0;
  }
  const hex = (x) => ('00000000' + (x>>>0).toString(16)).slice(-8);
  return hex(h0)+hex(h1)+hex(h2)+hex(h3)+hex(h4)+hex(h5)+hex(h6)+hex(h7);
}

function hmacSha256Hex(key, msg) {
  let k;
  const keyBytes = [];
  for (let i = 0; i < key.length; i++) keyBytes.push(key.charCodeAt(i) & 0xff);
  if (keyBytes.length > 64) {
    const h = sha256(key);
    k = [];
    for (let i = 0; i < 32; i++) k.push(parseInt(h.substr(i*2,2),16));
  } else {
    k = keyBytes.slice();
  }
  while (k.length < 64) k.push(0);
  const ipad = k.map(b => b ^ 0x36);
  const opad = k.map(b => b ^ 0x5c);
  const inner = ipad.map(b => String.fromCharCode(b)).join('') + msg;
  const innerHash = sha256(inner);
  let innerRaw = '';
  for (let i = 0; i < innerHash.length; i += 2) innerRaw += String.fromCharCode(parseInt(innerHash.substr(i, 2), 16));
  const outer = opad.map(b => String.fromCharCode(b)).join('') + innerRaw;
  return sha256(outer);
}

const item = $input.first().json;
const payload = (item.body && typeof item.body === 'object') ? item.body : item;
const { executionId, nonce, ts, signature } = payload;
let verified = false;
let rejectReason = '';
if (!executionId || !nonce || !ts || !signature) {
  rejectReason = 'missing signature fields';
} else {
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - Number(ts)) > 300) {
    rejectReason = 'stale timestamp';
  } else {
    const expected = hmacSha256Hex($env.WEBHOOK_TOKEN, executionId + '.' + nonce + '.' + ts);
    const a = Buffer.from(expected, 'hex');
    const b = Buffer.from(signature, 'hex');
    verified = a.length === b.length && a.equals(b);
    if (!verified) rejectReason = 'bad signature';
  }
}
return { json: { ...item, ...payload, verified, rejectReason } };

const lead = $('Lead').first().json;
const b = (lead.body && typeof lead.body === 'object') ? lead.body : lead;
const rdap = $input.first().json;
const events = rdap.events || [];
const created = (events.find(e => e.eventAction === 'registration') || {}).eventDate || '';
const updated = (events.find(e => e.eventAction === 'last changed') || {}).eventDate || '';
return { json: {
  executionId: b.executionId,
  name: b.name,
  email: b.email,
  company: b.company || '',
  domain: b.email.split('@')[1] || '',
  registrar: (rdap.registrar || {}).ldhName || '',
  created,
  updated,
  status: (rdap.status || []).join(', '),
  nameservers: (rdap.nameservers || []).map(ns => ns.ldhName || '').join(', ')
} };
